"""Whole pinned timeconv.c: separate normalization and Gregorian stages."""
def register(topic,q,detail):
 def lesson(title,why,principle,use,reading,questions,cards):
  topic(title,'시간','kernel/time/timeconv.c','time64_to_tm',why,principle,use,reading,*(q(*x) for x in questions),details=[detail(*x) for x in cards])
 lesson('Unix 초를 날짜 필드로·time64_to_tm의 계약',
  '하나의 초 숫자가 연·월·일·요일로 바뀌는 변환의 입력·출력 단위를 배웁니다.',
  'totalsecs는1970-01-01 00:00:00 UTC부터의 초이며 offset은 더할 초입니다. 함수는 kernel struct tm의 시·분·초·날짜·요일·연중 일수를 채웁니다. tm_year는1900 이후 연수, tm_mon은1월0부터11, tm_mday는1부터입니다. void 반환이며 timezone 이름·DST 규칙을 조회하지 않습니다.',
  '초 값과 이미 결정한 offset초를 전달하고 결과 필드의 서로 다른 기준을 표시할 때 변환합니다. 커널 tm_year는long이라 사용자 libc struct tm과 필드 폭을 무조건 같다고 가정하지 않습니다.',
  '함수 주석의 epoch·offset과 마지막 tm 필드 대입, time.h의 struct tm을 연결하세요.',
  [('2024년1월1일을 tm 형식으로 표시할 연·월 값은?','tm_year=124,tm_mon=0이다','tm_year=2024,tm_mon=1이다','연은1900을 뺀 값이고 월은0부터입니다. 날짜 표시에 각각1900·1을 다시 더합니다.'),('offset초를 주면 지역의 DST 규칙도 자동 조회하는가?','아니며 정해진 초 offset만 적용한다','지역 이름으로 시간대 DB를 조회한다','입력에는 지역 이름이나 DST 규칙 객체가 없습니다. 오프셋 결정과 달력 변환을 분리합니다.')],
  [('부분 헤더','time.h는 struct tm을 연결해 읽습니다. 이 수업으로 time.h 전체 API의 해설이 끝났다고 계산하지 않습니다.'),('윤초','초를86400일 길이로 분해해0..59를 출력합니다. 별도 윤초 테이블을 적용하는 변환이라고 확대하지 않습니다.')])
 lesson('음수 Unix 초의 하루 몫·나머지 보정',
  'C의0방향 나눗셈과 날짜에 필요한 이전 날·양수 하루 위치를 구분합니다.',
  '먼저 div_s64_rem(totalsecs,86400)으로 days와 remainder를 얻습니다. C signed 나눗셈은0방향이므로 -1초의 초기 days는0,remainder는-1입니다. rem<0 보정에서86400을 더하고 days를1내려 최종 전날23:59:59가 됩니다. 나머지를 그대로 시로 분해하면 음수 필드가 생깁니다.',
  '음수 epoch도 허용하는 날짜 변환에서 하루 위치를0<=rem<86400으로 먼저 정규화합니다. 정규화 후 시·분·초를 읽고 quotient·remainder 부호 규약을 확인합니다.',
  'div_s64_rem과 두 while 보정을 -1초 예제로 따라가세요.',
  [('-1초·offset0의 보정 후 days와 rem은?','days=-1,rem=86399다','days=0,rem=-1이 최종 날짜다','하루의 위치를 양수로 만들면서 하루 번호를 이전 날로 내립니다.'),('음수 보정이 필요한 이유는?','C0방향 몫과 달력의 하루 위치 규약이 다르다','1970년 이전에는 하루가 음수 길이다','시간 길이86400은 같습니다. 음수 나눗셈의 몫·나머지 표현을 정규화하는 문제입니다.')],
  [('시각 분해','정규화 후 hour=rem/3600,나머지의 min=/60,sec=%60입니다.'),('범위','days·rem은long입니다. long32의 입력 범위와 int offset 더하기는 long64 검증 결과로 자동 보장하지 않습니다.')])
 lesson('초 offset으로 날짜 경계를 넘기·정규화 반복',
  '지역 오프셋이 같은 UTC 순간을 전날·다음 날 날짜로 바꾸는 방식을 배웁니다.',
  'offset은 totalsecs 전체에 직접 합하지 않고 하루 나머지 rem에 더합니다. rem>=86400이면 하루를 빼며 days를 올리고 rem<0이면 하루를 더하며 days를 내립니다. 큰 int offset은 여러 날을 움직여 여러 번 반복합니다. 상수 시간이라는 무조건적 설명과 구분합니다.',
  '오프셋은초로 전달하고 timezone 정책으로 이미 선택한 값을 사용합니다. long 폭이 충분한 구성에서는 s64초 자체와offset의 합을 먼저 overflow시키지 않는 분해를 이해합니다.',
  'rem+=offset 뒤 두 반복문의 days 증감 방향을 읽으세요.',
  [('Unix0초에 offset=-3600초를 주면?','1969-12-31 23:00:00이다','1970-01-01 01:00:00이다','기준 자정에서 한 시간을 빼므로 전날 마지막 시간이 됩니다.'),('offset=172800초는 날짜를 얼마나 옮기는가?','정규화로2일 뒤가 된다','offset은 하루 이내로 자동 잘린다','입력은초이며 modulo만 하고 days를 버리지 않습니다. 반복마다 하루 번호를 함께 바꿉니다.')],
  [('폭 계약','long64에서 rem+int offset을 확인합니다. long32에 같은 최대int를 섞는 산술 안전성은 별도로 점검해야 합니다.'),('사용 의미','offset 보정은 표시 날짜를 계산합니다. 시스템 clock 설정이나 타이머 예약을 수행하지 않습니다.')])
 lesson('요일 modulo·1970년 목요일과 음수 나머지',
  '일 번호를7일 주기로 줄이되 음수 C 나머지를0..6으로 보정하는 원리를 배웁니다.',
  '1970-01-01은목요일이며 tm_wday의 일요일0 규약에서4입니다. (4+days)%7을 계산하고 결과가 음수이면7을 더합니다. 이 days는 이미 offset으로 조정한 날짜 번호여서 오프셋이 날짜를 넘으면 요일도 같이 바뀝니다.',
  '요일0..6 규약과 epoch요일 기준을 함께 사용합니다. 음수 결과를 배열 인덱스로 바로 사용하지 않고 정규화된 출력값을 확인합니다.',
  'tm_wday 계산과 음수 보정 조건을 읽으세요.',
  [('days=-1의 tm_wday는?','3이며 수요일이다','-1이며 음수 요일이다','epoch목요일4에서 하루를 빼3이 됩니다. 요일 번호는0..6을 사용합니다.'),('C %7이 음수이면 어떻게 하는가?','7을 더해0..6으로 보정한다','절댓값만 취한다','예를 들어 -1의 올바른 주기 위치는6입니다. 절댓값1은 다른 요일입니다.')],
  [('주기','7을 더하거나 빼도 같은 주기 동치류입니다. 대표값만0..6으로 고릅니다.'),('날짜 연결','시·분만 offset 적용하고 UTC days로 요일을 구하면 자정 경계에서 틀릴 수 있습니다.')])
 lesson('3월 시작 계산 달력·윤년을 마지막에 두기',
  '불규칙한2월을 계산 연도의 끝으로 옮겨 월·일 계산을 단순화하는 원리를 배웁니다.',
  '원문 계산 달력은3월을month2,다음1월12,2월13으로 놓습니다. 3월1일은연중0,4월1일31,1월1일306,2월28일364이고 윤년2월29일365입니다. 2월의 추가 하루가 연말로 가므로3월부터 월 시작 위치는 그 해의 윤년 여부에 영향받지 않습니다.',
  '중간 month·day_of_year를 표시용 Gregorian 필드와 구분합니다. 306경계에서1·2월인지 판단하고 마지막에 연·월·연중일을 변환합니다.',
  '함수의 계산 달력 주석과 is_Jan_or_Feb 조건을 읽으세요.',
  [('계산 달력에서1월1일의0기준 연중 위치는?','306이다','0이다','시작점은3월1일입니다. 표시용1월 시작 연중일과 다른 중간 값입니다.'),('3월 시작이 주는 이점은?','윤일을 계산 연도 끝에 둬 앞선 월 위치를 고정한다','윤년을 완전히 없애 어떤 연도도365일이다','윤년 자체는 존재합니다. 추가 하루의 위치를 계산하기 편한 곳으로 옮깁니다.')],
  [('원리 출처','원문이 연결한 Neri·Schneider 논문 Proposition6.3의 계산 달력 역변환을 사용합니다. 월 번호는 원문 주석처럼 tm 규약에 맞춰 달라집니다.'),('출처 링크','https://arxiv.org/abs/2102.06959 ; 계산식의 적용 범위·정수 몫을 함께 읽습니다.')])
 lesson('큰 unsigned 날짜 이동·epoch 상수와400년 주기',
  '음수 날짜까지 양의 계산 구간으로 옮기는 큰 상수를 임의 숫자와 구분합니다.',
  'udays=(u64)days+2305843009213814918이며 이 상수는2^61+120966입니다. u64 변환·덧셈은 modulo2^64로 계산하고 그 다음4*udays+3도unsigned 산술입니다. Unix epoch를3월 시작 계산 달력의 큰 연도로 옮긴 뒤 마지막6313183731940000년을 빼며 이 연수는400의 배수입니다. Gregorian 달력의400년 반복을 보존합니다.',
  '상수를 줄이거나 signed 곱으로 바꾸지 말고 형식·wrap·epoch 보정을 함께 추적합니다. 유한형 구현의 동치를 수학의 무한정수 산술과 무조건 같다고 설명하지 않습니다.',
  'udays 변환과4배·마지막year 상수 차이를 읽으세요.',
  [('이 코드의 큰 epoch 이동을 읽을 때 필요한 것은?','u64형식·modulo연산·마지막 연도 보정을 함께 추적한다','상수는 보기 불편하므로 임의로1000으로 바꾼다','앞뒤 변환의 동치를 유지하는 상수입니다. 한 부분만 바꾸면 날짜 기준이 깨집니다.'),('Gregorian400년 주기에 포함된 날짜 수는?','146097일이다','정확히146000일이다','400*365에97윤일을 더합니다.4년·100년·400년 예외가 합쳐진 주기입니다.')],
  [('검증','독립400년 주기·일반 연월 순회 모델로long64의 MIN/MAX초와 int offset 경계를 비교합니다.'),('폭','source days와tm_year는long입니다. native32 ABI의 전체s64 입력 보장으로 이 검사를 확대하지 않습니다.')])
 lesson('날짜의 세기·세기 안 연도·2939745 곱 분해',
  '여러 해를 순회하지 않고 몫·나머지와 곱의 상하위 비트로 연도를 얻는 방법을 배웁니다.',
  '4*udays+3을146097로 나눈 몫이 century이며 나머지/4가 day_of_century입니다. 다시 n=4*day_of_century+3에2939745를 곱합니다. 상위32비트가 year_of_century,하위32비트/2939745/4가 계산 연중일입니다. 제한된 중간 범위에서 나눗셈·나머지 동치를 활용하는 식이며 모든u32값에 대한 임의 공식이 아닙니다.',
  '중간 범위와 비트 절단을 확인하고 u64 곱을 유지합니다. century라는 변수 이름을 단순 days/36500으로 대체하지 않으며4년과세기 윤년 예외를 함께 봅니다.',
  'div64_u64_rem·upper_32_bits·lower_32_bits와 year 합을 읽으세요.',
  [('2939745 곱의 상위32비트를 사용하는 목적은?','세기 안의 계산 연도를 얻는다','시간대의 초 offset을 얻는다','달력 역변환의 연도 분해 단계입니다. 시간대 offset은 앞선 하루 정규화에 이미 반영됐습니다.'),('하위 비트도 함께 쓰는 이유는?','계산 연중일 정보를 얻는다','검사 없이 곱 overflow를 오류로 반환한다','같은 곱에서 몫과 잔여 위치를 구합니다. boolean overflow API와 다른 계산입니다.')],
  [('형식','2939745ULL을 사용해 곱 폭을u64로 확보합니다. u32곱을 먼저 계산한 뒤 확대하면 상위 정보가 사라질 수 있습니다.'),('증명 범위','원문 알고리즘·논문의 유효 중간 구간을 기준으로 읽습니다. 다른 날짜 기준에 숫자만 복사하지 않습니다.')])
 lesson('세기 윤년 예외·year_of_century와century 분기',
  '4년 주기에100년 제외·400년 포함을 반영하는 실제 조건식을 배웁니다.',
  'year_of_century가0이 아니면 그 값%4가0인지로 윤년을 정합니다. 세기 경계의0이면 century%4가0인지 검사해400년 배수 세기만 윤년으로 선택합니다. 일반 Gregorian 규칙 year%4==0 && (year%100!=0 || year%400==0)을 분해한 형태입니다.',
  '1900·2000·2100 같은 세기 경계와2월말에서 확인합니다. 계산 달력의3월 시작 연도와 마지막1·2월 연도 이동을 함께 고려합니다.',
  'is_leap_year의 조건 연산자와 연중일 보정을 읽으세요.',
  [('Gregorian1900년과2000년 중 윤년은?','2000년만 윤년이다','둘 다4의 배수이므로 윤년이다','100년 배수는 보통 제외하지만400년 배수는 다시 포함합니다.'),('year_of_century=0이면 어떤 기준을 쓰는가?','century가4의 배수인지 본다','0이4의 배수니까 모든 세기를 윤년으로 한다','세기의 번호4주기는 전체400년 주기입니다.100년 예외를 처리하는 별도 분기입니다.')],
  [('기준','연중일을 Gregorian1월 시작으로 바꿀 때3월 이후에31+28+윤년여부를 더합니다.'),('관찰','2월28→29→3월1 경계와 nonleap2월28→3월1을 서로 비교합니다.')])
 lesson('월·일을 곱과shift로·2141과132377의 범위',
  '월 길이 배열을 순회하는 대신 제한된 연중일을 정수 식으로 분해하는 기술을 배웁니다.',
  'n=2141*day_of_year+132377의 상위16비트 n>>16이 계산 month이며 하위16비트((u16)n)/2141이0기준day입니다. 논문의1기준 월 상수197913보다65536작은132377은 tm식 월 번호 조정에 맞습니다. day_of_year가 계산 연도0..365라는 구간에서 사용하는 식입니다.',
  '곱·상수·폭·shift·u16 cast를 함께 유지하고 전월 마지막 날과다음월 첫날을 비교합니다. 임의 큰 day_of_year 입력이나 다른 month 기준에 적용하지 않습니다.',
  'u32tmp·month·day의 세 대입을 읽으세요.',
  [('day는 표시 날짜가 되기 전에 어떤 기준인가?','월의0기준 날짜다','1970년부터 누적 초다','마지막 day+1로 tm_mday의1기준 날짜를 만듭니다. 중간 표현 기준을 확인합니다.'),('u16 cast는 어떤 정보를 남기는가?','곱의 하위16비트를 남긴다','곱 전체를128비트로 늘린다','2^16 나머지에 해당하는 정보를 사용합니다. 상위16비트로 구한 월과 같은 곱에서 분해합니다.')],
  [('상수 비교','197913-65536=132377입니다. 달력 원리 출처의1기준 월과 Linux중간2기준3월 번호 차이를 연결합니다.'),('성능 범위','연·월 배열 순회를 피하는 산술 구조입니다. 모든CPU에서 실제 속도가 더 빠르다는 측정 결과로 확대하지 않습니다.')])
 lesson('계산 날짜를tm으로·306 경계와연중일 복원',
  '3월 기준 날짜를 사용자에게 익숙한1월 기준 날짜로 되돌리는 마지막 단계를 배웁니다.',
  'day_of_year>=306이면1·2월이므로 year에1을 더하고 month에서12를 뺍니다. day는1을 더해1기준으로 만들며 연중일은1·2월이면306을 빼고 나머지는31+28+윤년여부를 더합니다. epoch 연수 보정 후 tm_year는year-1900으로 저장합니다.',
  '중간 계산 달력과 최종 출력값을 구분해1월1일·2월말·3월1일의 year,month,yday를 점검합니다. unsigned 연중일의 -306 덧셈도 해당 분기의 유효값에서modulo산술로 의도한 차이가 되는지 확인합니다.',
  'is_Jan_or_Feb와 year·month·day·day_of_year 보정 및 최종 대입을 읽으세요.',
  [('계산 연중일306의 최종 tm_yday는?','0이며1월1일이다','306이며11월 날짜다','1·2월 분기에서306을 뺍니다. 계산 달력의1월1일이 Gregorian연중0이 됩니다.'),('계산3월1일의 최종 yday는?','평년59·윤년60이다','항상0이다','Gregorian1월31일+2월28일 또는29일을 앞에 둡니다. 계산 연중0을 표시용 기준으로 이동합니다.')],
  [('연도 경계','1·2월은 계산 연도의 마지막이므로 Gregorian표시 연도는1증가합니다.'),('전체 파일 범위','timeconv.c 전체 scalar변환을 해설합니다. 시간대 DB·윤초·clocksource·NTP와 타이머 구현은 이 파일에서 수행하지 않습니다.')])
